const nf = (n, digits=2) => Number(n).toLocaleString('ru-RU',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const time = ms => new Date(ms).toLocaleTimeString('ru-RU',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'});
const dateTime = ms => new Date(ms).toLocaleDateString('ru-RU',{timeZone:'UTC',day:'2-digit',month:'2-digit'})+' '+time(ms);
const NOW=Date.parse('2026-09-09T12:00:00Z');
