const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
function hydrateIcons(){ $$('i[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);}); }
const S={view:'overview',asset:'BTC',period:15,steps:4,role:'arbiter',scenario:'ready',job:null,paused:false,riskTight:false,request:9001,history:9001,positions:[{id:501,asset:'BTC',direction:'long',margin:10,leverage:10,entry:64100,pnl:1.25}],events:[],nextPosition:502};
const price=()=>S.asset==='BTC'?64250.5:2674.32;
const symbol=()=>S.asset+'USDT';
const duration=(period=S.period,steps=S.steps)=>{const mins=period*steps;return mins%1440===0?`${mins/1440} дн.`:mins%60===0?`${mins/60} ч`:`${mins} мин`;};
const isExpired=()=>S.scenario==='expired'||S.history===8998;
const until=()=>time(NOW+(isExpired()?-3600000:S.steps*S.period*60000));
const modelNames={bull:'deepseek-v4-pro',bear:'minimax-m3',arbiter:'glm-5.2'};
function roles(){return ['bull','bear','arbiter'].map(role=>({role,name:role==='arbiter'?'Арбитр':role==='bull'?'Bull':'Bear',model:modelNames[role],state:S.scenario==='partial'&&role==='arbiter'?'failed':'completed',direction:role==='bear'?'Снижение':'Рост'}));}
function data(){
  const scale=price()/64250.5; const candles=[]; const count=24; let last=price()-310*scale;
  for(let i=0;i<count;i++){
    const close=price()+(i-count+1)*12.4*scale+Math.sin(i*.82)*50*scale+Math.cos(i*1.9)*17*scale;
    const c=i===count-1?price():close;
    candles.push({t:NOW-(count-i)*S.period*60000,o:last,c,h:Math.max(last,c)+(17+(i*13)%32)*scale,l:Math.min(last,c)-(12+(i*17)%29)*scale,v:8+(i*17)%37});last=c;
  }
  const role=S.role, sign=role==='bear'?-1:1, amount=(role==='bull'?235:role==='bear'?160:180)*scale;
  const points=Array.from({length:S.steps},(_,i)=>{const fraction=(i+1)/S.steps; const p=price()+sign*(amount*fraction+Math.sin(fraction*Math.PI*2)*18*scale);const range=(38+fraction*47)*scale;return{step:i+1,t:NOW+(i+1)*S.period*60000,p,low:p-range,high:p+range};});
  return{candles,points};
}
function roleRows(){return roles().map(r=>`<div class="role-row"><span class="role-letter">${r.name[0]}</span><div class="role-detail"><strong>${r.name}</strong><small>${r.model}</small></div><span class="role-result ${r.state==='failed'?'warning':r.role==='bear'?'negative':'positive'}">${r.state==='failed'?'Нет ответа':r.direction}</span></div>`).join('');}
function positionsHTML(){
 if(!S.positions.length)return `<div class="empty-state"><strong>Нет открытых позиций</strong><p>Рассчитайте условия перед открытием учебной позиции.</p><button class="text-btn" data-go="overview">Перейти к рынку ${icon('arrow')}</button></div>`;
 return S.positions.map(p=>`<div class="position-row"><div><strong>${p.asset}USDT <span class="muted">#${p.id}</span></strong><small><span class="${p.direction==='long'?'positive':'negative'}">${p.direction==='long'?'Long':'Short'} ×${p.leverage}</span> · ${nf(p.margin)} USDT</small></div><div class="position-entry"><small>Цена входа</small><strong>${nf(p.entry)}</strong></div><div><small>После издержек</small><strong class="${p.pnl>=0?'positive':'negative'}">${p.pnl>0?'+':''}${nf(p.pnl)} USDT</strong></div><button class="text-btn" data-close-position="${p.id}">Закрыть ${icon('close')}</button></div>`).join('');
}
