function systemHTML(){return `<article class="panel system-intro"><span class="dot blue"></span><div><h2>Данные прототипа</h2><p>Локальные сценарии не подключены к рабочим сервисам. Доступность реального WORED здесь не проверяется.</p></div><button class="btn subtle" id="scenarioSystem">${icon('sliders')} Сменить сценарий</button></article><div class="system-grid">${[['Источники данных',[['Рыночная цена','На '+(S.scenario==='stale'?'11:58:29':'11:59:55')+' UTC'],['Результат прогноза','#'+S.request+' · 12:00 UTC'],['PostgreSQL / Redis','Не подключены'],['Модели','Примеры, без API вызовов']]],['Учёт и ограничения',[['Реальные операции','Отключены'],['Inference-запросы','0'],['Денежные списания','0'],['Данные','Демонстрационные']]]].map(([title,rows])=>`<article class="panel"><div class="panel-head"><h2>${title}</h2></div>${rows.map(([k,v])=>`<div class="service-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</article>`).join('')}</div>`;}
let chartObserver=null, chartGeometry=null;
function render(){chartObserver?.disconnect();$('#overview').innerHTML=overviewHTML();$('#research').innerHTML=researchHTML();$('#session').innerHTML=sessionHTML();$('#system').innerHTML=systemHTML();bindViews();hydrateIcons();showView(S.view,false);chartObserver=new ResizeObserver(()=>{if(S.view==='overview')drawChart();});chartObserver.observe($('#chartStage'));requestAnimationFrame(drawChart);}
const titles={overview:['Обзор','ОБЗОР РЫНКА','Рынок и сценарий','Цена, прогноз и условия действия — в одном рабочем окне.'],session:['Сессия','УПРАВЛЕНИЕ ИСПОЛНЕНИЕМ','Дневная сессия','План, условия входа и контроль учебных позиций.'],research:['Исследование','ЛАБОРАТОРИЯ ПРОГНОЗОВ','Сценарии и аргументы','Сохранённые расчёты, роли моделей и оценка результата.'],system:['Система','СОСТОЯНИЕ И ОГРАНИЧЕНИЯ','Система','Источники данных и границы текущего рабочего режима.']};
function showView(view,scroll=true){if(!titles[view])view='overview';S.view=view;$$('.view').forEach(el=>el.hidden=el.id!==view);$$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const [crumb,eye,title,sub]=titles[view];$('#breadcrumb').textContent=crumb;$('#eyebrow').textContent=eye;$('#pageTitle').textContent=title;$('#pageSubtitle').textContent=sub;history.replaceState(null,'','#'+view);if(scroll)window.scrollTo({top:0,behavior:'instant'});if(view==='overview')requestAnimationFrame(drawChart);}
function bindViews(){
 $$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));
 $$('[data-period]').forEach(b=>b.onclick=()=>{S.period=Number(b.dataset.period);render();});
 $('#assetSelect').onchange=e=>{S.asset=e.target.value;render();};$('#roleSelect').onchange=e=>{S.role=e.target.value;render();};
 $('#openPoints').onclick=()=>{showView('research');$('.table-scroll').scrollIntoView({block:'center'});$('.table-scroll').focus({preventScroll:true});};
 $$('[data-trade]').forEach(b=>b.onclick=()=>openTrade(b.dataset.trade,b));
 $$('[data-close-position]').forEach(b=>b.onclick=()=>askClose([Number(b.dataset.closePosition)],b));
 $('#newForecast').onclick=()=>{showView('research');$('#forecastForm').scrollIntoView({block:'center'});$('[name="steps"]',$('#forecastForm')).focus({preventScroll:true});};
 $('[data-retry]')?.addEventListener('click',()=>applyScenario('ready'));
 $('#forecastForm').oninput=()=>{const f=$('#forecastForm');$('#forecastDuration').textContent=`${f.steps.value} × ${f.period.value} мин = ${duration(Number(f.period.value),Number(f.steps.value))}`;};
 $('#forecastForm').onsubmit=e=>{e.preventDefault();startForecast();};
 $$('[data-history]').forEach(b=>b.onclick=()=>{S.history=Number(b.dataset.history);render();});
 $('#pauseSession').onclick=()=>{S.paused=!S.paused;S.events.unshift(['12:00',S.paused?'Сессия приостановлена':'Сессия продолжена','Изменение в локальном прототипе.']);render();toast(S.paused?'Сессия приостановлена':'Сессия продолжена');};
 $('#tightenRisk').onclick=()=>{S.riskTight=true;S.events.unshift(['12:00','Риск ужесточён','Применён консервативный режим в прототипе.']);render();toast('Консервативный режим применён');};
 $('#closeAll').onclick=e=>askClose(S.positions.map(p=>p.id),e.currentTarget);
 $('#scenarioSystem').onclick=e=>openDialog($('#scenarioDialog'),e.currentTarget);
}
function svgText(x,y,text,attrs=''){return `<text x="${x}" y="${y}" fill="#a3a3a3" font-size="10" font-family="Segoe UI, sans-serif" ${attrs}>${esc(text)}</text>`;}
function drawChart(){
 const svg=$('#marketChart'),stage=$('#chartStage');if(!svg||stage.clientWidth<10||S.view!=='overview')return;
 const W=stage.clientWidth,H=stage.clientHeight,mobile=W<500,left=8,right=mobile?64:74,top=28,axisBottom=H-28,volBottom=axisBottom-20,volTop=volBottom-40,priceBottom=volTop-24,plotWidth=W-left-right;
 const {candles,points}=data(),visiblePoints=isExpired()?[]:points;
 const all=[...candles.flatMap(c=>[c.h,c.l]),price(),...visiblePoints.flatMap(p=>[p.low,p.high])];
 const rawMin=Math.min(...all),rawMax=Math.max(...all),pad=(rawMax-rawMin)*.13||1;
 const min=rawMin-pad,max=rawMax+pad; const start=candles[0].t-S.period*60000*.5,end=NOW+S.period*60000*(Math.max(S.steps,4)+.7);
 const x=t=>left+(t-start)/(end-start)*plotWidth,y=p=>priceBottom-(p-min)/(max-min)*(priceBottom-top),xNow=x(NOW),stepWidth=x(NOW+S.period*60000)-xNow;
 svg.setAttribute('viewBox',`0 0 ${W} ${H}`);let out=`<defs><clipPath id="priceClip"><rect x="${left}" y="${top}" width="${plotWidth}" height="${priceBottom-top}"/></clipPath></defs>`;
 out+=`<rect x="${xNow}" y="${top}" width="${W-right-xNow}" height="${priceBottom-top}" fill="#122038" opacity=".42"/>`;
 for(let i=0;i<=5;i++){const val=min+(max-min)*i/5,py=y(val);out+=`<line x1="${left}" y1="${py}" x2="${W-right}" y2="${py}" stroke="#2a2a2a" stroke-width="1"/>`+svgText(W-right+9,py+3,nf(val,0));}
 out+=svgText(W-right+9,14,'USDT','font-size="9"');
 const tickCount=mobile?4:6;for(let i=0;i<=tickCount;i++){const t=start+(end-start)*i/tickCount;const rounded=Math.round(t/(S.period*60000))*S.period*60000;const px=x(rounded);if(px<left||px>W-right)continue;out+=`<line x1="${px}" y1="${top}" x2="${px}" y2="${volBottom}" stroke="#242424" stroke-dasharray="2 4"/>`+svgText(px,axisBottom+11,S.period===240?dateTime(rounded):time(rounded),'text-anchor="middle"');}
 out+=svgText(W-right+9,axisBottom+11,'UTC','font-size="9"');
 const maxVolume=Math.max(...candles.map(c=>c.v));
 out+=`<g clip-path="url(#priceClip)">`;
 for(const c of candles){const px=x(c.t),color=c.c>=c.o?'#67d99b':'#e98186',bodyWidth=Math.max(2,Math.min(11,stepWidth*.56));out+=`<line data-candle-wick x1="${px}" y1="${y(c.h)}" x2="${px}" y2="${y(c.l)}" stroke="${color}" stroke-width="1.2"/><rect data-candle-body x="${px-bodyWidth/2}" y="${Math.min(y(c.o),y(c.c))}" width="${bodyWidth}" height="${Math.max(1.2,Math.abs(y(c.o)-y(c.c)))}" fill="${color}" rx=".6"/>`;}
 if(visiblePoints.length){const path=(field)=>`M${xNow},${y(price())} `+visiblePoints.map(p=>`L${x(p.t)},${y(p[field])}`).join(' ');const poly=`${xNow},${y(price())} `+visiblePoints.map(p=>`${x(p.t)},${y(p.high)}`).join(' ')+' '+[...visiblePoints].reverse().map(p=>`${x(p.t)},${y(p.low)}`).join(' ');out+=`<polygon data-forecast-range points="${poly}" fill="#3b82f6" opacity=".13"/><path d="${path('high')}" stroke="#82b1ff" stroke-width="1" stroke-dasharray="4 4" fill="none"/><path d="${path('low')}" stroke="#82b1ff" stroke-width="1" stroke-dasharray="4 4" fill="none"/><path data-forecast-line d="${path('p')}" stroke="#74a7ff" stroke-width="2.3" stroke-linejoin="round" fill="none"/>`;visiblePoints.forEach(p=>out+=`<circle data-forecast-point cx="${x(p.t)}" cy="${y(p.p)}" r="${S.steps>12?1.7:2.7}" fill="#141414" stroke="#93c5fd" stroke-width="1.5"/>`);}
 out+='</g>';
 const py=y(price());out+=`<line x1="${left}" y1="${py}" x2="${W-right}" y2="${py}" stroke="#7bdba1" stroke-dasharray="3 4" opacity=".5"/><rect x="${W-right+2}" y="${py-10}" width="${right-3}" height="21" rx="3" fill="#224531"/>`+svgText(W-right+7,py+4,nf(price(),mobile?0:1),'fill="#bcf5d0" font-size="9"');
 out+=`<line x1="${xNow}" y1="${top-6}" x2="${xNow}" y2="${volBottom}" stroke="#b3bac6" stroke-dasharray="4 4" opacity=".65"/>`+svgText(xNow,15,'Сейчас','text-anchor="middle" fill="#d4d4d4" font-size="9"');
 out+=`<line x1="${left}" y1="${volTop-8}" x2="${W-right}" y2="${volTop-8}" stroke="#303030"/>`+svgText(left+3,volTop+1,'Объём · '+S.asset,'font-size="8"');
 for(const c of candles){const px=x(c.t),height=c.v/maxVolume*28;out+=`<rect data-volume-bar x="${px-Math.min(11,stepWidth*.56)/2}" y="${volBottom-height}" width="${Math.max(2,Math.min(11,stepWidth*.56))}" height="${height}" fill="${c.c>=c.o?'#2f664b':'#693d40'}"/>`;}
 out+=svgText(W-right+9,volTop+6,String(maxVolume),'font-size="9"')+svgText(W-right+9,volBottom,'0','font-size="9"');
 out+=`<g id="crosshair" style="display:none"><line id="crossX" stroke="#929292" stroke-dasharray="3 3"/><line id="crossY" stroke="#929292" stroke-dasharray="3 3"/></g>`;
 svg.innerHTML=out;chartGeometry={x,y,min,max,left,top,W,H,priceBottom,plotWidth,start,end,candles,points:visiblePoints,right};
 setOHLC(candles.at(-1));
 svg.onpointermove=chartHover;svg.onpointerleave=()=>{$('#chartTooltip').hidden=true;$('#crosshair').style.display='none';setOHLC(candles.at(-1));};
}
function setOHLC(c){$('#ohlc').innerHTML=`<span>${dateTime(c.t)} UTC</span><span>O <b>${nf(c.o)}</b></span><span>H <b>${nf(c.h)}</b></span><span>L <b>${nf(c.l)}</b></span><span>C <b>${nf(c.c)}</b></span>`;}
function chartHover(event){const g=chartGeometry,box=event.currentTarget.getBoundingClientRect(),px=event.clientX-box.left,py=event.clientY-box.top;if(px<g.left||px>g.W-g.right||py<g.top||py>g.priceBottom)return;const t=g.start+(px-g.left)/g.plotWidth*(g.end-g.start);const candidates=[...g.candles,...g.points];const nearest=candidates.reduce((a,b)=>Math.abs(a.t-t)<Math.abs(b.t-t)?a:b);const cx=g.x(nearest.t);$('#crosshair').style.display='';const set=(sel,a)=>Object.entries(a).forEach(([k,v])=>$(sel).setAttribute(k,v));set('#crossX',{x1:cx,y1:g.top,x2:cx,y2:g.priceBottom});set('#crossY',{x1:g.left,y1:py,x2:g.W-g.right,y2:py});const tooltip=$('#chartTooltip');tooltip.hidden=false;tooltip.innerHTML=`<strong>${dateTime(nearest.t)} UTC</strong>`+(nearest.o!==undefined?`O ${nf(nearest.o)} · C ${nf(nearest.c)}<br>H ${nf(nearest.h)} · L ${nf(nearest.l)}`:`Прогноз ${nf(nearest.p)} USDT<br>Диапазон ${nf(nearest.low)}–${nf(nearest.high)}`);tooltip.style.left=Math.min(Math.max(8,cx-80),g.W-tooltip.offsetWidth-4)+'px';tooltip.style.top=Math.min(Math.max(8,py-80),g.H-tooltip.offsetHeight-5)+'px';if(nearest.o!==undefined)setOHLC(nearest);}
let toastTimer;function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
const dialogOrigins=new WeakMap();function openDialog(dialog,origin){dialogOrigins.set(dialog,origin||document.activeElement);dialog.showModal();document.body.style.overflow='hidden';const heading=$('[tabindex="-1"]',dialog);heading?.focus();}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.style.overflow='';const origin=dialogOrigins.get(d);if(origin?.isConnected)origin.focus();else $('#pageTitle').focus();});});
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
let tradeDirection='long',previewVersion=0,previewTimer,previewValid=false;
function openTrade(direction,origin){tradeDirection=direction;const title=direction==='long'?'Long':'Short';$('#tradeTitle').textContent='Учебная позиция '+title;$('#tradeConfirm').textContent='Открыть учебный '+title;$('#ticketSymbol').textContent=symbol();$('#ticketPrice').textContent=nf(price())+' USDT';openDialog($('#tradeDialog'),origin);updatePreview();}
function updatePreview(){const version=++previewVersion;clearTimeout(previewTimer);previewValid=false;$('#tradeConfirm').disabled=true;$('#previewStatus').className='preview-status pending';$('#previewStatus').textContent='Пересчитываем условия…';previewTimer=setTimeout(()=>{if(version!==previewVersion)return;const f=$('#tradeForm'),margin=Number(f.margin.value),leverage=Number(f.leverage.value),reserved=S.positions.reduce((a,p)=>a+p.margin,0);if(!f.checkValidity()||margin>100-reserved||S.scenario==='stale'){$('#previewStatus').className='preview-status error';$('#previewStatus').textContent=S.scenario==='stale'?'Цена устарела. Новый вход недоступен.':margin>100-reserved?'Недостаточно свободного учебного бюджета.':'Проверьте маржу: допустимо 1–100 USDT.';$('#ticketFacts').innerHTML='';$('#ticketNet').textContent='—';return;}const notional=margin*leverage,qty=notional/price(),entryFee=notional*.00055,exitFee=notional*1.01*.00055,distance=(1/leverage-.005)*100,liq=price()*(1+(tradeDirection==='long'?-1:1)*distance/100);$('#previewStatus').className='preview-status';$('#previewStatus').textContent='Предварительный расчёт готов · цена на 11:59:55 UTC';$('#ticketFacts').innerHTML=[['Номинал',nf(notional)+' USDT'],['Объём',nf(qty,8)+' '+S.asset],['Комиссия входа',nf(entryFee,4)+' USDT'],['Комиссия выхода · оценка',nf(exitFee,4)+' USDT'],['Цена ликвидации',nf(liq)+' USDT'],['До ликвидации',nf(distance)+' %']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('');$('#ticketNet').textContent='+'+nf(notional*.01-entryFee-exitFee)+' USDT';previewValid=true;$('#tradeConfirm').disabled=false;},280);}
$('#tradeForm').addEventListener('input',updatePreview);$('#tradeForm').addEventListener('change',updatePreview);
$('#tradeForm').onsubmit=e=>{e.preventDefault();if(!previewValid||$('#tradeConfirm').disabled)return;previewValid=false;$('#tradeConfirm').disabled=true;const f=$('#tradeForm');S.positions.push({id:S.nextPosition++,asset:S.asset,direction:tradeDirection,margin:Number(f.margin.value),leverage:Number(f.leverage.value),entry:price(),pnl:-Number(f.margin.value)*Number(f.leverage.value)*.0011});$('#tradeDialog').close();render();toast('Учебная позиция добавлена в прототип. Рабочий WORED не изменён.');};
let closeIds=[];function askClose(ids,origin){closeIds=ids;$('#confirmTitle').textContent=ids.length>1?'Закрыть все учебные позиции?':'Закрыть учебную позицию?';$('#confirmText').textContent=`${ids.length>1?'Позиций: '+ids.length: 'Позиция #'+ids[0]}. Действие изменит только локальный список этого прототипа.`;$('#confirmAction').textContent=ids.length>1?'Закрыть все позиции':'Закрыть позицию';openDialog($('#confirmDialog'),origin);}
$('#confirmAction').onclick=()=>{S.positions=S.positions.filter(p=>!closeIds.includes(p.id));$('#confirmDialog').close();render();toast('Учебные позиции закрыты в прототипе.');};
let jobTimers=[];function startForecast(){if(S.job)return;const f=$('#forecastForm');if(!f.reportValidity())return;S.asset=f.symbol.value.startsWith('ETH')?'ETH':'BTC';S.period=Number(f.period.value);S.steps=Number(f.steps.value);S.scenario='ready';S.role='arbiter';S.history=++S.request;S.job='В очереди · #'+S.request;render();jobTimers.push(setTimeout(()=>{S.job='Рассчитывается · #'+S.request;render();},900));jobTimers.push(setTimeout(()=>{S.job=null;render();toast('Расчёт #'+S.request+' завершён в прототипе.');},2400));}
const scenarioDefs=[['ready','Свежие данные','Прогноз завершён, предварительный расчёт доступен.','green'],['stale','Данные устарели','Последняя цена сохранена. Новые входы заблокированы.','orange'],['partial','Частичный прогноз','Bull и Bear готовы, итог арбитра отсутствует.','orange'],['expired','Прогноз истёк','История доступна, действующего вывода нет.','gray'],['empty','Нет позиций','Пустой список с понятным следующим действием.','gray']];
$('#scenarioOptions').innerHTML=scenarioDefs.map(([v,h,p,c])=>`<button data-scenario="${v}"><b class="dot ${c}"></b><span><strong>${h}</strong><small>${p}</small></span></button>`).join('');
function applyScenario(value){jobTimers.forEach(clearTimeout);jobTimers=[];S.job=null;S.scenario=value;S.history=S.request;if(value==='partial')S.role='bull';else S.role='arbiter';if(value==='empty')S.positions=[];if($('#scenarioDialog').open)$('#scenarioDialog').close();render();toast(scenarioDefs.find(x=>x[0]===value)[1]);}
$$('[data-scenario]').forEach(b=>b.onclick=()=>applyScenario(b.dataset.scenario));
$('#scenarioButton').onclick=e=>openDialog($('#scenarioDialog'),e.currentTarget);
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
$('#refresh').onclick=()=>{if(S.scenario==='stale')applyScenario('ready');else toast('Срез прототипа обновлён · 12:00 UTC');};
window.addEventListener('hashchange',()=>showView(location.hash.slice(1)||'overview'));
S.view=titles[location.hash.slice(1)]?location.hash.slice(1):'overview';
render();
